// Point d'entrée serverless Vercel : réutilise l'app Express partagée.
// Toutes les requêtes /api/* sont routées ici via vercel.json.
import app from '../server/app.js'

export default app

import 'dotenv/config'
import express from 'express'
import cors from 'cors'
import { usePg } from './db.js'
import { authRouter, requireAuth } from './auth.js'
import { apiRouter } from './routes.js'

/**
 * Construit l'application Express (sans démarrer de serveur).
 * - en local : `server/index.js` appelle `app.listen()` ;
 * - sur Vercel : `api/index.js` exporte directement cette app comme
 *   fonction serverless (une app Express est un handler `(req, res)`).
 */
const app = express()
app.use(cors())
app.use(express.json())

// public
app.get('/api/health', (req, res) => res.json({ status: 'ok' }))
app.use('/api/auth', authRouter)

// protégé : toutes les routes de données exigent un token valide
app.use('/api', requireAuth, apiRouter)

// gestion d'erreurs centralisée
app.use((err, req, res, _next) => {
  const status = err.status || 500
  if (status === 500) console.error('[api]', err)
  res.status(status).json({ error: err.message || 'Erreur serveur.' })
})

export { usePg }
export default app

import { Router } from 'express'
import jwt from 'jsonwebtoken'
import bcrypt from 'bcryptjs'

/**
 * Authentification admin unique (pas d'inscription).
 * Identifiants et secret configurables par variables d'environnement :
 *   ADMIN_USERNAME      (défaut: "admin")
 *   ADMIN_PASSWORD      (défaut: "medicastock" — À CHANGER en production)
 *   JWT_SECRET          (défaut: secret de dev — À CHANGER en production)
 *   TOKEN_TTL           (défaut: "8h")
 */
const ADMIN_USERNAME = process.env.ADMIN_USERNAME || 'admin'
const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || 'medicastock'
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-change-me-in-production'
const TOKEN_TTL = process.env.TOKEN_TTL || '8h'

// On hache le mot de passe au démarrage : aucun mot de passe en clair n'est comparé.
const ADMIN_HASH = bcrypt.hashSync(ADMIN_PASSWORD, 10)

if (!process.env.JWT_SECRET || !process.env.ADMIN_PASSWORD) {
  console.warn(
    '[auth] ⚠ Utilisation des identifiants/secret par défaut. ' +
      'Définissez ADMIN_USERNAME, ADMIN_PASSWORD et JWT_SECRET en production.',
  )
}

export const authRouter = Router()

authRouter.post('/login', (req, res) => {
  const { username, password } = req.body || {}
  const userOk = String(username || '') === ADMIN_USERNAME
  const passOk = bcrypt.compareSync(String(password || ''), ADMIN_HASH)
  if (!userOk || !passOk) {
    return res.status(401).json({ error: 'Identifiants incorrects.' })
  }
  const token = jwt.sign({ sub: ADMIN_USERNAME, role: 'admin' }, JWT_SECRET, { expiresIn: TOKEN_TTL })
  res.json({ token, user: { username: ADMIN_USERNAME, role: 'admin' } })
})

authRouter.get('/me', requireAuth, (req, res) => {
  res.json({ user: { username: req.user.sub, role: req.user.role } })
})

/** Middleware : exige un Bearer token valide. */
export function requireAuth(req, res, next) {
  const header = req.headers.authorization || ''
  const token = header.startsWith('Bearer ') ? header.slice(7) : null
  if (!token) return res.status(401).json({ error: 'Authentification requise.' })
  try {
    req.user = jwt.verify(token, JWT_SECRET)
    next()
  } catch {
    res.status(401).json({ error: 'Session expirée ou invalide.' })
  }
}

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import pg from 'pg'
import { seed } from './seedData.js'

const __dirname = dirname(fileURLToPath(import.meta.url))
const DATA_DIR = join(__dirname, 'data')
const DB_FILE = join(DATA_DIR, 'db.json')

/** Mode Postgres (Supabase) si DATABASE_URL est défini, sinon repli fichier JSON. */
export const usePg = !!process.env.DATABASE_URL

/* ─────────────── Postgres / Supabase ─────────────── */
export const pool = usePg
  ? new pg.Pool({
      connectionString: process.env.DATABASE_URL,
      ssl: { rejectUnauthorized: false }, // requis par le pooler Supabase
      max: 5,
      connectionTimeoutMillis: 8000,
    })
  : null

/* ─────────────── Repli fichier JSON ─────────────── */
let state

function load() {
  if (existsSync(DB_FILE)) {
    try {
      state = JSON.parse(readFileSync(DB_FILE, 'utf-8'))
      return
    } catch {
      // fichier corrompu -> ré-amorçage
    }
  }
  state = structuredClone(seed)
  save()
}

export function save() {
  if (usePg) return
  if (!existsSync(DATA_DIR)) mkdirSync(DATA_DIR, { recursive: true })
  writeFileSync(DB_FILE, JSON.stringify(state, null, 2), 'utf-8')
}

export function db() {
  if (!state) load()
  return state
}

export function nextId(collection, key) {
  return db()[collection].reduce((max, r) => Math.max(max, r[key]), 0) + 1
}

// amorce le fichier seulement en mode JSON
if (!usePg) load()

import app, { usePg } from './app.js'

const PORT = process.env.PORT || 4000

app.listen(PORT, () => {
  console.log(`[medicastock] API prête sur http://localhost:${PORT}`)
  console.log(`[medicastock] Persistance : ${usePg ? 'PostgreSQL / Supabase' : 'fichier JSON local (repli)'}`)
})

import { Router } from 'express'
import store from './store.js'

export const apiRouter = Router()

const ok = (handler) => async (req, res, next) => {
  try {
    res.json(await handler(req))
  } catch (err) {
    next(err)
  }
}

/* ── lectures ── */
apiRouter.get('/dashboard', ok(async () => ({
  medicaments: await store.getDashboardMedicaments(),
  nbPerimesTotal: await store.getNbPerimesTotal(),
})))
apiRouter.get('/medicaments', ok(() => store.getMedicamentsCatalogue()))
apiRouter.get('/stocks', ok(() => store.getStocksSynthese()))
apiRouter.get('/medicaments/:id/lots', ok((req) => store.getLotsForMedicament(Number(req.params.id))))
apiRouter.get('/services', ok(() => store.getServicesWithStats()))
apiRouter.get('/fournisseurs', ok(() => store.listFournisseurs()))
apiRouter.get('/familles', ok(() => store.listFamilles()))
apiRouter.get('/mouvements', ok((req) => {
  const { debut = '2000-01-01', fin = '2100-01-01' } = req.query
  return store.getMouvements(debut, fin)
}))
apiRouter.get('/statistiques', ok(() => store.getStatistiques()))
apiRouter.get('/exports/counts', ok(() => store.getExportCounts()))

// listes brutes utiles aux formulaires (selects)
apiRouter.get('/ref/medicaments', ok(() => store.listMedicaments()))
apiRouter.get('/ref/services', ok(() => store.listServices()))

/* ── écritures ── */
apiRouter.post('/medicaments', ok((req) => store.createMedicament(req.body || {})))
apiRouter.post('/fournisseurs', ok((req) => store.createFournisseur(req.body || {})))
apiRouter.post('/services', ok((req) => store.createService(req.body || {})))
apiRouter.post('/entrees', ok((req) => store.createEntree(req.body || {})))
apiRouter.post('/sorties', ok((req) => store.createSortie(req.body || {})))

/* ── éditions / suppressions ── */
apiRouter.put('/medicaments/:id', ok((req) => store.updateMedicament(req.params.id, req.body || {})))
apiRouter.delete('/medicaments/:id', ok((req) => store.deleteMedicament(req.params.id)))
apiRouter.put('/fournisseurs/:id', ok((req) => store.updateFournisseur(req.params.id, req.body || {})))
apiRouter.delete('/fournisseurs/:id', ok((req) => store.deleteFournisseur(req.params.id)))
apiRouter.put('/services/:id', ok((req) => store.updateService(req.params.id, req.body || {})))
apiRouter.delete('/services/:id', ok((req) => store.deleteService(req.params.id)))

import 'dotenv/config'
import { writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import pg from 'pg'

/**
 * Génère un jeu de données réaliste et COHÉRENT puis le charge :
 *   - dans Supabase/Postgres si DATABASE_URL est défini ;
 *   - sinon dans le fichier JSON local (server/data/db.json).
 *
 * Cohérence garantie :
 *   - chaque lot est rattaché à une entrée réelle et à un médicament ;
 *   - une sortie ne dépasse jamais la quantité restante d'un lot ;
 *   - date(sortie) ∈ [date(entrée du lot), aujourd'hui] ;
 *   - quantite_disponible d'un médicament = somme des quantités restantes de ses lots ;
 *   - péremptions réparties (certains lots déjà périmés).
 *
 * Reproductible : graine fixe (modifiable via SEED=...).
 */

const __dirname = dirname(fileURLToPath(import.meta.url))
const TODAY = new Date('2026-06-24T00:00:00Z')

/* ── PRNG déterministe (mulberry32) ── */
let _s = (Number(process.env.SEED) || 20260624) >>> 0
const rnd = () => {
  _s |= 0; _s = (_s + 0x6d2b79f5) | 0
  let t = Math.imul(_s ^ (_s >>> 15), 1 | _s)
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296
}
const ri = (min, max) => Math.floor(rnd() * (max - min + 1)) + min
const pick = (arr) => arr[Math.floor(rnd() * arr.length)]
const fmt = (d) => d.toISOString().slice(0, 10)
const addDays = (d, n) => { const x = new Date(d); x.setUTCDate(x.getUTCDate() + n); return x }
const daysBetween = (a, b) => Math.round((b - a) / 86400000)

/* ── référentiel réaliste (fixe) ── */
const familles = [
  'Antalgiques', 'Antibiotiques', 'Gastro-entérologie', 'Endocrinologie',
  'Pneumologie', 'Cardiologie', 'Dermatologie', 'Anti-inflammatoires',
].map((nom, i) => ({ ID_FAMILLE: i + 1, NOM_FAMILLE: nom }))

const fournisseurs = [
  ['PharmaLab SARL', '+229 01 23 45 67', 'contact@pharmalab.bj', 'Zone industrielle, Cotonou'],
  ['MediSource SA', '+229 02 11 22 33', 'ventes@medisource.com', 'Avenue Steinmetz, Cotonou'],
  ['BioPharma Bénin', '+229 03 44 55 66', 'info@biopharma.bj', 'Akpakpa, Cotonou'],
  ['Global Health Dist.', '+229 04 77 88 99', 'order@ghd.africa', 'Godomey, Abomey-Calavi'],
  ['AfriMed', '+229 05 10 20 30', 'afrimed@mail.com', 'Fidjrossè, Cotonou'],
  ['UbiPharm Bénin', '+229 06 55 44 33', 'commandes@ubipharm.bj', 'Zone portuaire, Cotonou'],
  ['Laborex Bénin', '+229 07 88 99 00', 'contact@laborex.bj', 'Cadjèhoun, Cotonou'],
  ['Cotonou Pharma Dépôt', '+229 09 12 34 56', 'depot@cotonoupharma.bj', 'Dantokpa, Cotonou'],
].map((f, i) => ({
  ID_FOURNISSEUR: i + 1, NOM_FOURNISSEUR: f[0], TELEPHONE: f[1], EMAIL: f[2], ADRESSE: f[3],
}))

const services = [
  ['Cardiologie', 'Service de cardiologie et soins cardiovasculaires'],
  ['Pédiatrie', 'Prise en charge des enfants'],
  ['Urgences', 'Service des urgences médicales'],
  ['Chirurgie', 'Bloc opératoire et soins post-opératoires'],
  ['Maternité', 'Suivi de grossesse et accouchements'],
  ['Réanimation', 'Soins intensifs'],
  ['Médecine interne', 'Pathologies médicales générales'],
  ['Oncologie', 'Traitement des cancers'],
  ['Néphrologie', 'Maladies rénales et dialyse'],
].map((s, i) => ({ ID_SERVICE: i + 1, NOM_SERVICE: s[0], DESCRIPTION: s[1] }))

// catalogue : [nom, id_famille]
const catalogue = [
  ['Paracétamol 500mg', 1], ['Paracétamol 1000mg', 1], ['Ibuprofène 400mg', 1],
  ['Tramadol 50mg', 1], ['Aspirine 500mg', 1], ['Codéine 30mg', 1],
  ['Amoxicilline 1g', 2], ['Ceftriaxone 1g', 2], ['Azithromycine 250mg', 2],
  ['Ciprofloxacine 500mg', 2], ['Métronidazole 500mg', 2], ['Doxycycline 100mg', 2],
  ['Oméprazole 20mg', 3], ['Ésoméprazole 40mg', 3], ['Dompéridone 10mg', 3],
  ['Lopéramide 2mg', 3], ['Ranitidine 150mg', 3],
  ['Insuline rapide', 4], ['Insuline lente', 4], ['Metformine 850mg', 4],
  ['Lévothyroxine 50µg', 4], ['Glimépiride 2mg', 4],
  ['Salbutamol aérosol', 5], ['Budésonide inhalateur', 5], ['Montélukast 10mg', 5],
  ['Théophylline 200mg', 5],
  ['Amlodipine 5mg', 6], ['Bisoprolol 5mg', 6], ['Furosémide 40mg', 6],
  ['Atorvastatine 20mg', 6], ['Énalapril 10mg', 6],
  ['Bétaméthasone crème', 7], ['Mupirocine pommade', 7], ['Kétoconazole crème', 7],
  ['Diclofénac 50mg', 8], ['Prednisolone 20mg', 8], ['Naproxène 500mg', 8],
]
const medicaments = catalogue.map(([nom, fam], i) => ({
  ID_MEDICAMENT: i + 1, NOM_MEDICAMENT: nom, ID_FAMILLE: fam,
  QUANTITE_SEUIL: ri(20, 80), QUANTITE_DISPONIBLE: 0, // rempli après les lots
}))

/* ── entrées (réceptions) réparties sur ~14 mois ── */
const NB_ENTREES = 40
const entrees = Array.from({ length: NB_ENTREES }, (_, i) => {
  const date = addDays(TODAY, -ri(20, 430))
  return { ID_ENTREE: i + 1, DATE_ENTREE: fmt(date), _d: date, FOURNISSEUR: pick(fournisseurs).NOM_FOURNISSEUR }
}).sort((a, b) => a._d - b._d).map((e, i) => ({ ...e, ID_ENTREE: i + 1 }))

/* ── lots : 1 à 4 par médicament, rattachés à une entrée ── */
const lots = []
let idLot = 1
for (const m of medicaments) {
  const nb = ri(1, 4)
  for (let k = 0; k < nb; k++) {
    const e = pick(entrees)
    const init = ri(40, 400)
    // péremption 4 à 30 mois après l'entrée (certaines déjà passées)
    const perem = addDays(e._d, ri(120, 900))
    lots.push({
      ID_LOT: idLot++, ID_MEDICAMENT: m.ID_MEDICAMENT, QUANTITE: init,
      DATE_PEREMPTION: fmt(perem), ID_ENTREE: e.ID_ENTREE, _entreeDate: e._d,
    })
  }
}

/* ── sorties : distribution réaliste vers les services ── */
const sorties = []
let idSortie = 1
const TARGET_SORTIES = 180
let attempts = 0
while (sorties.length < TARGET_SORTIES && attempts < 4000) {
  attempts++
  const lot = pick(lots)
  if (lot.QUANTITE <= 0) continue
  const span = daysBetween(lot._entreeDate, TODAY)
  if (span < 1) continue
  const take = Math.min(lot.QUANTITE, ri(3, 40))
  const qte = ri(1, take)
  const date = addDays(lot._entreeDate, ri(1, span))
  lot.QUANTITE -= qte
  sorties.push({
    ID_SORTIE: idSortie++, ID_SERVICE: pick(services).ID_SERVICE,
    ID_LOT: lot.ID_LOT, QUANTITE: qte, DATE_SORTIE: fmt(date),
  })
}

/* ── stock courant = somme des quantités restantes des lots ── */
for (const m of medicaments) {
  m.QUANTITE_DISPONIBLE = lots
    .filter((l) => l.ID_MEDICAMENT === m.ID_MEDICAMENT)
    .reduce((s, l) => s + l.QUANTITE, 0)
}

// nettoyage des champs internes
const cleanLots = lots.map(({ _entreeDate, ...l }) => l)
const cleanEntrees = entrees.map(({ _d, ...e }) => e)
const data = { familles, fournisseurs, services, medicaments, entrees: cleanEntrees, lots: cleanLots, sorties }

/* ── résumé ── */
const perimes = cleanLots.filter((l) => l.QUANTITE > 0 && new Date(l.DATE_PEREMPTION) < TODAY).length
const critiques = medicaments.filter((m) => m.QUANTITE_DISPONIBLE < m.QUANTITE_SEUIL).length
const summary = `${medicaments.length} médicaments · ${cleanLots.length} lots · ${cleanEntrees.length} entrées · ${sorties.length} sorties · ${perimes} lots périmés · ${critiques} sous seuil`

/* ── chargement ── */
async function loadPg() {
  const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false } })
  const client = await pool.connect()
  const insert = async (table, cols, rows) => {
    if (!rows.length) return
    const ph = rows
      .map((_, i) => '(' + cols.map((__, j) => `$${i * cols.length + j + 1}`).join(',') + ')')
      .join(',')
    const vals = rows.flatMap((r) => cols.map((c) => r[c.toUpperCase()] ?? r[c]))
    await client.query(`INSERT INTO ${table} (${cols.join(',')}) VALUES ${ph}`, vals)
  }
  try {
    await client.query('BEGIN')
    await client.query('TRUNCATE sorties, lots, entrees, medicaments, services, fournisseurs, familles RESTART IDENTITY CASCADE')
    await insert('familles', ['id_famille', 'nom_famille'], familles)
    await insert('fournisseurs', ['id_fournisseur', 'nom_fournisseur', 'telephone', 'email', 'adresse'], fournisseurs)
    await insert('services', ['id_service', 'nom_service', 'description'], services)
    await insert('medicaments', ['id_medicament', 'nom_medicament', 'id_famille', 'quantite_disponible', 'quantite_seuil'], medicaments)
    await insert('entrees', ['id_entree', 'date_entree', 'fournisseur'], cleanEntrees)
    await insert('lots', ['id_lot', 'id_medicament', 'quantite', 'date_peremption', 'id_entree'], cleanLots)
    await insert('sorties', ['id_sortie', 'id_service', 'id_lot', 'quantite', 'date_sortie'], sorties)
    // recaler les séquences
    for (const [t, c] of [['familles', 'id_famille'], ['fournisseurs', 'id_fournisseur'], ['services', 'id_service'], ['medicaments', 'id_medicament'], ['entrees', 'id_entree'], ['lots', 'id_lot'], ['sorties', 'id_sortie']]) {
      await client.query(`SELECT setval(pg_get_serial_sequence('${t}','${c}'), (SELECT COALESCE(MAX(${c}),1) FROM ${t}))`)
    }
    await client.query('COMMIT')
    console.log('✅ Supabase rempli :', summary)
  } catch (e) {
    await client.query('ROLLBACK')
    throw e
  } finally {
    client.release()
    await pool.end()
  }
}

function loadJson() {
  const dir = join(__dirname, 'data')
  if (!existsSync(dir)) mkdirSync(dir, { recursive: true })
  writeFileSync(join(dir, 'db.json'), JSON.stringify(data, null, 2), 'utf-8')
  console.log('✅ Fichier JSON rempli :', summary)
}

try {
  if (process.env.DATABASE_URL) await loadPg()
  else loadJson()
} catch (e) {
  console.error('❌ Échec du seed :', e.message)
  process.exit(1)
}

import { db, save, nextId } from '../db.js'

/* ─────────────── helpers ─────────────── */
const familleName = (id) => db().familles.find((f) => f.ID_FAMILLE === id)?.NOM_FAMILLE ?? '—'
const medOfLot = (idLot) => {
  const lot = db().lots.find((l) => l.ID_LOT === idLot)
  return lot ? db().medicaments.find((m) => m.ID_MEDICAMENT === lot.ID_MEDICAMENT) : null
}
const isPerime = (dateStr) => new Date(dateStr) < new Date(new Date().toDateString())

/* ─────────────── sélecteurs (≈ requêtes SQL) ─────────────── */

export function getDashboardMedicaments() {
  const { medicaments, lots } = db()
  return medicaments
    .map((m) => ({
      ID_MEDICAMENT: m.ID_MEDICAMENT,
      NOM_MEDICAMENT: m.NOM_MEDICAMENT,
      NOM_FAMILLE: familleName(m.ID_FAMILLE),
      QUANTITE_DISPONIBLE: m.QUANTITE_DISPONIBLE,
      QUANTITE_SEUIL: m.QUANTITE_SEUIL,
      NB_LOTS_PERIMES: lots.filter(
        (l) => l.ID_MEDICAMENT === m.ID_MEDICAMENT && l.QUANTITE > 0 && isPerime(l.DATE_PEREMPTION),
      ).length,
    }))
    .sort((a, b) => a.NOM_MEDICAMENT.localeCompare(b.NOM_MEDICAMENT))
}

export function getNbPerimesTotal() {
  return db().lots.filter((l) => l.QUANTITE > 0 && isPerime(l.DATE_PEREMPTION)).length
}

export function getMedicamentsCatalogue() {
  return db()
    .medicaments.map((m) => ({
      ID_MEDICAMENT: m.ID_MEDICAMENT,
      NOM_MEDICAMENT: m.NOM_MEDICAMENT,
      NOM_FAMILLE: familleName(m.ID_FAMILLE),
      QUANTITE_DISPONIBLE: m.QUANTITE_DISPONIBLE,
      QUANTITE_SEUIL: m.QUANTITE_SEUIL,
    }))
    .sort((a, b) => a.NOM_MEDICAMENT.localeCompare(b.NOM_MEDICAMENT))
}

export function getStocksSynthese() {
  const { medicaments, lots } = db()
  return medicaments
    .map((m) => {
      const ls = lots.filter((l) => l.ID_MEDICAMENT === m.ID_MEDICAMENT)
      return {
        ID_MEDICAMENT: m.ID_MEDICAMENT,
        NOM_MEDICAMENT: m.NOM_MEDICAMENT,
        NOM_FAMILLE: familleName(m.ID_FAMILLE),
        QUANTITE_DISPONIBLE: m.QUANTITE_DISPONIBLE,
        QUANTITE_SEUIL: m.QUANTITE_SEUIL,
        NB_LOTS: ls.length,
        QTE_TOTALE_LOTS: ls.reduce((s, l) => s + l.QUANTITE, 0),
        QTE_BONNE: ls.filter((l) => !isPerime(l.DATE_PEREMPTION)).reduce((s, l) => s + l.QUANTITE, 0),
        QTE_PERIMEE: ls.filter((l) => isPerime(l.DATE_PEREMPTION)).reduce((s, l) => s + l.QUANTITE, 0),
      }
    })
    .sort((a, b) => a.NOM_MEDICAMENT.localeCompare(b.NOM_MEDICAMENT))
}

export function getLotsForMedicament(idMed) {
  const { lots, entrees } = db()
  return lots
    .filter((l) => l.ID_MEDICAMENT === idMed)
    .map((l) => {
      const e = entrees.find((en) => en.ID_ENTREE === l.ID_ENTREE)
      return {
        ID_LOT: l.ID_LOT,
        QUANTITE: l.QUANTITE,
        DATE_PEREMPTION: l.DATE_PEREMPTION,
        DATE_ENTREE: e?.DATE_ENTREE ?? null,
        FOURNISSEUR: e?.FOURNISSEUR ?? null,
      }
    })
    .sort((a, b) => new Date(a.DATE_PEREMPTION) - new Date(b.DATE_PEREMPTION))
}

export function getServicesWithStats() {
  const { services, sorties } = db()
  return services
    .map((s) => {
      const ss = sorties.filter((so) => so.ID_SERVICE === s.ID_SERVICE)
      return {
        ID_SERVICE: s.ID_SERVICE,
        NOM_SERVICE: s.NOM_SERVICE,
        DESCRIPTION: s.DESCRIPTION,
        NB_SORTIES: ss.length,
        TOTAL_SORTIES: ss.reduce((acc, so) => acc + so.QUANTITE, 0),
      }
    })
    .sort((a, b) => a.NOM_SERVICE.localeCompare(b.NOM_SERVICE))
}

export function getMouvements(dateDebut, dateFin) {
  const { entrees, lots, sorties, services } = db()
  const d1 = new Date(dateDebut)
  const d2 = new Date(dateFin)
  d2.setDate(d2.getDate() + 1)

  const entreesMvt = entrees
    .filter((e) => {
      const d = new Date(e.DATE_ENTREE)
      return d >= d1 && d <= d2
    })
    .map((e) => {
      const ls = lots.filter((l) => l.ID_ENTREE === e.ID_ENTREE)
      return {
        ID_ENTREE: e.ID_ENTREE,
        DATE_ENTREE: e.DATE_ENTREE,
        FOURNISSEUR: e.FOURNISSEUR,
        NB_LOTS: ls.length,
        QUANTITE: ls.reduce((s, l) => s + l.QUANTITE, 0),
        TYPE_MVT: 'Entrée',
      }
    })

  const groups = {}
  sorties
    .filter((so) => {
      const d = new Date(so.DATE_SORTIE)
      return d >= d1 && d <= d2
    })
    .forEach((so) => {
      const key = `${so.DATE_SORTIE}|${so.ID_SERVICE}`
      if (!groups[key]) {
        groups[key] = {
          ID_ENTREE: so.ID_SORTIE,
          DATE_ENTREE: so.DATE_SORTIE,
          FOURNISSEUR: services.find((s) => s.ID_SERVICE === so.ID_SERVICE)?.NOM_SERVICE ?? '',
          NB_LOTS: 0,
          QUANTITE: 0,
          TYPE_MVT: 'Sortie',
        }
      }
      groups[key].NB_LOTS += 1
      groups[key].QUANTITE += so.QUANTITE
      groups[key].ID_ENTREE = Math.min(groups[key].ID_ENTREE, so.ID_SORTIE)
    })

  return [...entreesMvt, ...Object.values(groups)].sort(
    (a, b) => new Date(b.DATE_ENTREE) - new Date(a.DATE_ENTREE),
  )
}

export function getStatistiques() {
  const { services, sorties, medicaments, fournisseurs, lots, familles, entrees } = db()

  const topServices = services
    .map((s) => {
      const ss = sorties.filter((so) => so.ID_SERVICE === s.ID_SERVICE)
      return {
        NOM_SERVICE: s.NOM_SERVICE,
        NB_SORTIES: ss.length,
        TOTAL_UNITES: ss.reduce((acc, so) => acc + so.QUANTITE, 0),
      }
    })
    .filter((s) => s.TOTAL_UNITES > 0)
    .sort((a, b) => b.TOTAL_UNITES - a.TOTAL_UNITES)

  const medAgg = {}
  sorties.forEach((so) => {
    const m = medOfLot(so.ID_LOT)
    if (!m) return
    if (!medAgg[m.ID_MEDICAMENT]) medAgg[m.ID_MEDICAMENT] = { NOM_MEDICAMENT: m.NOM_MEDICAMENT, NB_SORTIES: 0, TOTAL_UNITES: 0 }
    medAgg[m.ID_MEDICAMENT].NB_SORTIES += 1
    medAgg[m.ID_MEDICAMENT].TOTAL_UNITES += so.QUANTITE
  })
  const topMedicaments = Object.values(medAgg).sort((a, b) => b.TOTAL_UNITES - a.TOTAL_UNITES)

  const totalEntrees = lots.reduce((s, l) => s + l.QUANTITE, 0)
  const totalSorties = sorties.reduce((s, so) => s + so.QUANTITE, 0)
  const totalPerime = lots.filter((l) => isPerime(l.DATE_PEREMPTION)).reduce((s, l) => s + l.QUANTITE, 0)
  const globalStats = {
    NB_MEDICAMENTS: medicaments.length,
    NB_SERVICES: services.length,
    NB_FOURNISSEURS: fournisseurs.length,
    TOTAL_SORTIES: totalSorties,
    TOTAL_ENTREES: totalEntrees,
    TOTAL_PERIME: totalPerime,
  }

  const moisAgg = {}
  entrees.forEach((e) => {
    const mois = e.DATE_ENTREE.slice(0, 7)
    const qte = lots.filter((l) => l.ID_ENTREE === e.ID_ENTREE).reduce((s, l) => s + l.QUANTITE, 0)
    if (!moisAgg[mois]) moisAgg[mois] = { MOIS: mois, ENTREE_UNITES: 0, SORTIE_UNITES: 0 }
    moisAgg[mois].ENTREE_UNITES += qte
  })
  sorties.forEach((so) => {
    const mois = so.DATE_SORTIE.slice(0, 7)
    if (!moisAgg[mois]) moisAgg[mois] = { MOIS: mois, ENTREE_UNITES: 0, SORTIE_UNITES: 0 }
    moisAgg[mois].SORTIE_UNITES += so.QUANTITE
  })
  const mensuel = Object.values(moisAgg).sort((a, b) => a.MOIS.localeCompare(b.MOIS))

  const famillesRep = familles
    .map((f) => {
      const ms = medicaments.filter((m) => m.ID_FAMILLE === f.ID_FAMILLE)
      return {
        NOM_FAMILLE: f.NOM_FAMILLE,
        NB_MEDICAMENTS: ms.length,
        TOTAL_STOCK: ms.reduce((s, m) => s + m.QUANTITE_DISPONIBLE, 0),
      }
    })
    .sort((a, b) => b.TOTAL_STOCK - a.TOTAL_STOCK)

  return { topServices, topMedicaments, globalStats, mensuel, familles: famillesRep }
}

