export function createEntree({ id_medicament, id_fournisseur, quantite, date_peremption }) {
  const idMed = Number(id_medicament)
  const idFour = Number(id_fournisseur)
  const qte = Number(quantite)
  const med = db().medicaments.find((m) => m.ID_MEDICAMENT === idMed)
  const four = db().fournisseurs.find((f) => f.ID_FOURNISSEUR === idFour)
  if (!med) throw httpError(400, 'Médicament invalide.')
  if (!four) throw httpError(400, 'Fournisseur invalide.')
  if (!Number.isFinite(qte) || qte <= 0) throw httpError(400, 'Quantité invalide.')
  if (!date_peremption) throw httpError(400, 'Date de péremption requise.')

  const today = new Date().toISOString().slice(0, 10)
  const entree = {
    ID_ENTREE: nextId('entrees', 'ID_ENTREE'),
    DATE_ENTREE: today,
    FOURNISSEUR: four.NOM_FOURNISSEUR,
  }
  const lot = {
    ID_LOT: nextId('lots', 'ID_LOT'),
    ID_MEDICAMENT: idMed,
    QUANTITE: qte,
    DATE_PEREMPTION: String(date_peremption),
    ID_ENTREE: entree.ID_ENTREE,
  }
  db().entrees.push(entree)
  db().lots.push(lot)
  med.QUANTITE_DISPONIBLE += qte
  save()
  return { entree, lot, medicament: med }
}

export function createSortie({ id_medicament, id_service, quantite }) {
  const idMed = Number(id_medicament)
  const idSvc = Number(id_service)
  const qte = Number(quantite)
  const med = db().medicaments.find((m) => m.ID_MEDICAMENT === idMed)
  const svc = db().services.find((s) => s.ID_SERVICE === idSvc)
  if (!med) throw httpError(400, 'Médicament invalide.')
  if (!svc) throw httpError(400, 'Service invalide.')
  if (!Number.isFinite(qte) || qte <= 0) throw httpError(400, 'Quantité invalide.')
  if (qte > med.QUANTITE_DISPONIBLE) throw httpError(400, `Stock insuffisant (disponible : ${med.QUANTITE_DISPONIBLE}).`)

  const lots = db()
    .lots.filter((l) => l.ID_MEDICAMENT === idMed && l.QUANTITE > 0)
    .sort((a, b) => new Date(a.DATE_PEREMPTION) - new Date(b.DATE_PEREMPTION))
  const today = new Date().toISOString().slice(0, 10)
  let reste = qte
  const created = []
  for (const lot of lots) {
    if (reste <= 0) break
    const prise = Math.min(lot.QUANTITE, reste)
    lot.QUANTITE -= prise
    reste -= prise
    const sortie = {
      ID_SORTIE: nextId('sorties', 'ID_SORTIE'),
      ID_SERVICE: idSvc,
      ID_LOT: lot.ID_LOT,
      QUANTITE: prise,
      DATE_SORTIE: today,
    }
    db().sorties.push(sortie)
    created.push(sortie)
  }
  med.QUANTITE_DISPONIBLE -= qte
  const sousSeuil = med.QUANTITE_DISPONIBLE < med.QUANTITE_SEUIL
  save()
  return { sorties: created, medicament: med, sousSeuil }
}

export function updateMedicament(id, { nom_medicament, id_famille, quantite_seuil }) {
  const med = db().medicaments.find((m) => m.ID_MEDICAMENT === Number(id))
  if (!med) throw httpError(404, 'Médicament introuvable.')
  const nom = String(nom_medicament ?? med.NOM_MEDICAMENT).trim()
  if (!nom) throw httpError(400, 'Le nom du médicament est obligatoire.')
  const idFamille = id_famille != null ? Number(id_famille) : med.ID_FAMILLE
  if (!db().familles.some((f) => f.ID_FAMILLE === idFamille)) throw httpError(400, 'Famille invalide.')
  med.NOM_MEDICAMENT = nom
  med.ID_FAMILLE = idFamille
  if (quantite_seuil != null && Number.isFinite(Number(quantite_seuil))) {
    med.QUANTITE_SEUIL = Number(quantite_seuil)
  }
  save()
  return med
}

export function deleteMedicament(id) {
  const idMed = Number(id)
  const idx = db().medicaments.findIndex((m) => m.ID_MEDICAMENT === idMed)
  if (idx === -1) throw httpError(404, 'Médicament introuvable.')
  if (db().lots.some((l) => l.ID_MEDICAMENT === idMed)) {
    throw httpError(400, 'Suppression impossible : ce médicament possède des lots en stock.')
  }
  db().medicaments.splice(idx, 1)
  save()
  return { ok: true }
}

export function updateFournisseur(id, { nom_fournisseur, telephone, email, adresse }) {
  const f = db().fournisseurs.find((x) => x.ID_FOURNISSEUR === Number(id))
