import { pool } from '../db.js'

/* Toutes les requêtes aliasent les colonnes en MAJUSCULES et formatent les dates
   en 'YYYY-MM-DD' pour reproduire exactement le contrat de l'ancien store JSON. */

const q = async (text, params) => (await pool.query(text, params)).rows
const one = async (text, params) => (await pool.query(text, params)).rows[0]

function httpError(status, message) {
  const e = new Error(message)
  e.status = status
  return e
}

