              COALESCE((SELECT SUM(l.quantite)::int FROM lots l WHERE l.id_entree = e.id_entree), 0) AS "QUANTITE",
              'Entrée' AS "TYPE_MVT"
       FROM entrees e
       WHERE e.date_entree BETWEEN $1 AND $2
       UNION ALL
       SELECT MIN(so.id_sortie) AS "ID_ENTREE",
