export async function getStatistiques() {
  const topServices = await q(`
    SELECT s.nom_service AS "NOM_SERVICE",
           COUNT(so.id_sortie)::int AS "NB_SORTIES",
           SUM(so.quantite)::int AS "TOTAL_UNITES"
    FROM services s
    JOIN sorties so ON so.id_service = s.id_service
    GROUP BY s.id_service, s.nom_service
    HAVING SUM(so.quantite) > 0
    ORDER BY "TOTAL_UNITES" DESC`)

  const topMedicaments = await q(`
    SELECT m.nom_medicament AS "NOM_MEDICAMENT",
           COUNT(so.id_sortie)::int AS "NB_SORTIES",
           SUM(so.quantite)::int AS "TOTAL_UNITES"
    FROM sorties so
    JOIN lots l ON l.id_lot = so.id_lot
    JOIN medicaments m ON m.id_medicament = l.id_medicament
    GROUP BY m.id_medicament, m.nom_medicament
    ORDER BY "TOTAL_UNITES" DESC`)

  const globalStats = await one(`
    SELECT (SELECT COUNT(*)::int FROM medicaments) AS "NB_MEDICAMENTS",
           (SELECT COUNT(*)::int FROM services) AS "NB_SERVICES",
           (SELECT COUNT(*)::int FROM fournisseurs) AS "NB_FOURNISSEURS",
           (SELECT COALESCE(SUM(quantite), 0)::int FROM sorties) AS "TOTAL_SORTIES",
           (SELECT COALESCE(SUM(quantite), 0)::int FROM lots) AS "TOTAL_ENTREES",
           (SELECT COALESCE(SUM(quantite), 0)::int FROM lots WHERE date_peremption < CURRENT_DATE) AS "TOTAL_PERIME"`)

  const mensuel = await q(`
    WITH e AS (
      SELECT to_char(en.date_entree, 'YYYY-MM') AS mois, COALESCE(SUM(l.quantite), 0)::int AS ent
      FROM entrees en LEFT JOIN lots l ON l.id_entree = en.id_entree
      GROUP BY 1
    ), s AS (
      SELECT to_char(date_sortie, 'YYYY-MM') AS mois, SUM(quantite)::int AS sor
      FROM sorties GROUP BY 1
    )
    SELECT COALESCE(e.mois, s.mois) AS "MOIS",
           COALESCE(e.ent, 0) AS "ENTREE_UNITES",
           COALESCE(s.sor, 0) AS "SORTIE_UNITES"
    FROM e FULL OUTER JOIN s ON e.mois = s.mois
    ORDER BY "MOIS"`)

  const familles = await q(`
    SELECT f.nom_famille AS "NOM_FAMILLE",
           COUNT(m.id_medicament)::int AS "NB_MEDICAMENTS",
           COALESCE(SUM(m.quantite_disponible), 0)::int AS "TOTAL_STOCK"
    FROM familles f
    LEFT JOIN medicaments m ON m.id_famille = f.id_famille
    GROUP BY f.id_famille, f.nom_famille
    ORDER BY "TOTAL_STOCK" DESC`)

  return { topServices, topMedicaments, globalStats, mensuel, familles }
}

