export async function createMedicament({ nom_medicament, id_famille, quantite_seuil }) {
  const nom = String(nom_medicament || '').trim()
  const idFamille = Number(id_famille)
  if (!nom) throw httpError(400, 'Le nom du médicament est obligatoire.')
  const fam = await one(`SELECT 1 FROM familles WHERE id_famille = $1`, [idFamille])
  if (!fam) throw httpError(400, 'Famille invalide.')
  const seuil = Number.isFinite(Number(quantite_seuil)) ? Number(quantite_seuil) : 10
  return one(
