     RETURNING id_medicament AS "ID_MEDICAMENT", nom_medicament AS "NOM_MEDICAMENT",
               id_famille AS "ID_FAMILLE", quantite_disponible AS "QUANTITE_DISPONIBLE",
               quantite_seuil AS "QUANTITE_SEUIL"`,
    [nom, idFamille, seuil],
  )
}

