export async function createEntree({ id_medicament, id_fournisseur, quantite, date_peremption }) {
  const idMed = Number(id_medicament)
  const idFour = Number(id_fournisseur)
  const qte = Number(quantite)
  if (!Number.isFinite(qte) || qte <= 0) throw httpError(400, 'Quantité invalide.')
  if (!date_peremption) throw httpError(400, 'Date de péremption requise.')

  const client = await pool.connect()
  try {
    await client.query('BEGIN')
    const med = (await client.query(`SELECT * FROM medicaments WHERE id_medicament = $1 FOR UPDATE`, [idMed])).rows[0]
    const four = (await client.query(`SELECT nom_fournisseur FROM fournisseurs WHERE id_fournisseur = $1`, [idFour])).rows[0]
    if (!med) throw httpError(400, 'Médicament invalide.')
    if (!four) throw httpError(400, 'Fournisseur invalide.')

    const entree = (await client.query(
      `INSERT INTO entrees (date_entree, fournisseur) VALUES (CURRENT_DATE, $1)
       RETURNING id_entree AS "ID_ENTREE", to_char(date_entree,'YYYY-MM-DD') AS "DATE_ENTREE", fournisseur AS "FOURNISSEUR"`,
      [four.nom_fournisseur],
    )).rows[0]
    const lot = (await client.query(
      `INSERT INTO lots (id_medicament, quantite, date_peremption, id_entree) VALUES ($1, $2, $3, $4)
       RETURNING id_lot AS "ID_LOT", id_medicament AS "ID_MEDICAMENT", quantite AS "QUANTITE",
                 to_char(date_peremption,'YYYY-MM-DD') AS "DATE_PEREMPTION", id_entree AS "ID_ENTREE"`,
      [idMed, qte, String(date_peremption), entree.ID_ENTREE],
    )).rows[0]
    const medicament = (await client.query(
      `UPDATE medicaments SET quantite_disponible = quantite_disponible + $2 WHERE id_medicament = $1
       RETURNING id_medicament AS "ID_MEDICAMENT", nom_medicament AS "NOM_MEDICAMENT",
                 id_famille AS "ID_FAMILLE", quantite_disponible AS "QUANTITE_DISPONIBLE",
                 quantite_seuil AS "QUANTITE_SEUIL"`,
      [idMed, qte],
    )).rows[0]
    await client.query('COMMIT')
    return { entree, lot, medicament }
  } catch (err) {
    await client.query('ROLLBACK')
    throw err
  } finally {
    client.release()
  }
}

export async function createSortie({ id_medicament, id_service, quantite }) {
  const idMed = Number(id_medicament)
  const idSvc = Number(id_service)
  const qte = Number(quantite)
  if (!Number.isFinite(qte) || qte <= 0) throw httpError(400, 'Quantité invalide.')

  const client = await pool.connect()
  try {
    await client.query('BEGIN')
    const med = (await client.query(`SELECT * FROM medicaments WHERE id_medicament = $1 FOR UPDATE`, [idMed])).rows[0]
    const svc = (await client.query(`SELECT 1 FROM services WHERE id_service = $1`, [idSvc])).rows[0]
    if (!med) throw httpError(400, 'Médicament invalide.')
    if (!svc) throw httpError(400, 'Service invalide.')
    if (qte > med.quantite_disponible) throw httpError(400, `Stock insuffisant (disponible : ${med.quantite_disponible}).`)

    // FEFO : lots non vides, péremption la plus proche d'abord
    const lots = (await client.query(
      `SELECT id_lot, quantite FROM lots
       WHERE id_medicament = $1 AND quantite > 0
       ORDER BY date_peremption FOR UPDATE`,
      [idMed],
    )).rows

    let reste = qte
    const created = []
    for (const lot of lots) {
      if (reste <= 0) break
      const prise = Math.min(lot.quantite, reste)
      reste -= prise
      await client.query(`UPDATE lots SET quantite = quantite - $2 WHERE id_lot = $1`, [lot.id_lot, prise])
      const sortie = (await client.query(
        `INSERT INTO sorties (id_service, id_lot, quantite, date_sortie)
         VALUES ($1, $2, $3, CURRENT_DATE)
         RETURNING id_sortie AS "ID_SORTIE", id_service AS "ID_SERVICE", id_lot AS "ID_LOT",
                   quantite AS "QUANTITE", to_char(date_sortie,'YYYY-MM-DD') AS "DATE_SORTIE"`,
        [idSvc, lot.id_lot, prise],
      )).rows[0]
      created.push(sortie)
    }

    const medicament = (await client.query(
      `UPDATE medicaments SET quantite_disponible = quantite_disponible - $2 WHERE id_medicament = $1
       RETURNING id_medicament AS "ID_MEDICAMENT", nom_medicament AS "NOM_MEDICAMENT",
                 id_famille AS "ID_FAMILLE", quantite_disponible AS "QUANTITE_DISPONIBLE",
                 quantite_seuil AS "QUANTITE_SEUIL"`,
      [idMed, qte],
    )).rows[0]
    await client.query('COMMIT')
    return { sorties: created, medicament, sousSeuil: medicament.QUANTITE_DISPONIBLE < medicament.QUANTITE_SEUIL }
  } catch (err) {
    await client.query('ROLLBACK')
    throw err
  } finally {
    client.release()
  }
}

export async function updateMedicament(id, { nom_medicament, id_famille, quantite_seuil }) {
  const med = await one(`SELECT * FROM medicaments WHERE id_medicament = $1`, [Number(id)])
  if (!med) throw httpError(404, 'Médicament introuvable.')
  const nom = String(nom_medicament ?? med.nom_medicament).trim()
  if (!nom) throw httpError(400, 'Le nom du médicament est obligatoire.')
  const idFamille = id_famille != null ? Number(id_famille) : med.id_famille
  const fam = await one(`SELECT 1 FROM familles WHERE id_famille = $1`, [idFamille])
  if (!fam) throw httpError(400, 'Famille invalide.')
  const seuil = quantite_seuil != null && Number.isFinite(Number(quantite_seuil)) ? Number(quantite_seuil) : med.quantite_seuil
  return one(
    `UPDATE medicaments SET nom_medicament = $2, id_famille = $3, quantite_seuil = $4 WHERE id_medicament = $1
     RETURNING id_medicament AS "ID_MEDICAMENT", nom_medicament AS "NOM_MEDICAMENT",
               id_famille AS "ID_FAMILLE", quantite_disponible AS "QUANTITE_DISPONIBLE",
               quantite_seuil AS "QUANTITE_SEUIL"`,
    [Number(id), nom, idFamille, seuil],
  )
}

export async function deleteMedicament(id) {
  const has = await one(`SELECT 1 FROM lots WHERE id_medicament = $1 LIMIT 1`, [Number(id)])
  if (has) throw httpError(400, 'Suppression impossible : ce médicament possède des lots en stock.')
  const r = await pool.query(`DELETE FROM medicaments WHERE id_medicament = $1`, [Number(id)])
