const TOKEN_KEY = 'mc-token'
let expiryNotified = false

export const getToken = () => localStorage.getItem(TOKEN_KEY)
export const setToken = (t) => {
  if (t) localStorage.setItem(TOKEN_KEY, t)
  else localStorage.removeItem(TOKEN_KEY)
}

/**
 * Appel API JSON. Ajoute le Bearer token, parse la réponse et lève une erreur
 * portant le message du serveur. Sur 401, vide le token et notifie l'app.
 */
export async function apiFetch(path, { method = 'GET', body, auth = true } = {}) {
  const headers = {}
  if (body !== undefined) headers['Content-Type'] = 'application/json'
  const token = getToken()
  if (auth && token) headers.Authorization = `Bearer ${token}`

  const res = await fetch(`/api${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  })

  if (res.status === 401 && auth) {
    const hadToken = !!token
    setToken(null)
    window.dispatchEvent(new CustomEvent('mc-unauthorized'))
    // n'affiche le toast qu'une fois (plusieurs requêtes peuvent échouer en
    // parallèle) et seulement si l'utilisateur était connecté (session expirée).
    if (hadToken && !expiryNotified) {
      expiryNotified = true
      setTimeout(() => { expiryNotified = false }, 3000)
      window.dispatchEvent(new CustomEvent('mc-toast', {
        detail: { message: 'Session expirée. Veuillez vous reconnecter.', type: 'warning' },
      }))
    }
  }

  let data = null
  const text = await res.text()
  if (text) {
    try { data = JSON.parse(text) } catch { data = text }
  }

  if (!res.ok) {
    const message = (data && data.error) || `Erreur ${res.status}`
    throw new Error(message)
  }
  return data
}

export const api = {
  get: (path) => apiFetch(path),
  post: (path, body) => apiFetch(path, { method: 'POST', body }),
  put: (path, body) => apiFetch(path, { method: 'PUT', body }),
  del: (path) => apiFetch(path, { method: 'DELETE' }),
}

/** Affiche un toast global (écouté par <Toasts/>). */
export function toast(message, type = 'info') {
  window.dispatchEvent(new CustomEvent('mc-toast', { detail: { message, type } }))
}

