import { useEffect, useRef, useState } from 'react'
import gsap from 'gsap'

const reduced = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Reusable modal overlay. Closes on overlay click and Escape.
 * `variant` chooses the inner shell ("content" -> .modal-content,
 * "panel" -> .modal-panel). Entrance/exit are choreographed with GSAP;
 * unmount is deferred until the exit animation finishes.
 */
export default function Modal({ open, onClose, children, variant = 'content' }) {
  const [rendered, setRendered] = useState(open)
  const overlayRef = useRef(null)
  const panelRef = useRef(null)

  // mount as soon as we want it open
  useEffect(() => {
    if (open) setRendered(true)
  }, [open])

  // choreograph entrance / exit
  useEffect(() => {
    if (!rendered) return
    const overlay = overlayRef.current
    const panel = panelRef.current
    if (!overlay || !panel) return

    if (open) {
      if (reduced()) {
        gsap.set([overlay, panel], { autoAlpha: 1, y: 0, scale: 1 })
        return
      }
      const tl = gsap.timeline()
      tl.fromTo(overlay, { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.25, ease: 'power2.out' })
        .fromTo(
          panel,
          { autoAlpha: 0, y: 24, scale: 0.95 },
          { autoAlpha: 1, y: 0, scale: 1, duration: 0.45, ease: 'back.out(1.5)' },
          '-=0.12',
        )
      return () => tl.kill()
    }

    // exit
    if (reduced()) {
      setRendered(false)
      return
    }
    const tl = gsap.timeline({ onComplete: () => setRendered(false) })
    tl.to(panel, { autoAlpha: 0, y: 12, scale: 0.97, duration: 0.22, ease: 'power2.in' })
      .to(overlay, { autoAlpha: 0, duration: 0.2 }, '-=0.1')
    return () => tl.kill()
  }, [open, rendered])

  // escape to close + scroll lock while mounted
  useEffect(() => {
    if (!rendered) return
    const onKey = (e) => { if (e.key === 'Escape') onClose() }
    document.addEventListener('keydown', onKey)
    document.body.style.overflow = 'hidden'
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = ''
    }
  }, [rendered, onClose])

  if (!rendered) return null

  const innerClass = variant === 'panel' ? 'modal-panel' : 'modal-content'

  return (
    <div
      ref={overlayRef}
      className="modal-overlay open active"
      onClick={(e) => { if (e.target === e.currentTarget) onClose() }}
    >
      <div ref={panelRef} className={innerClass}>{children}</div>
    </div>
  )
}

