import { useEffect, useState } from 'react'

const ICONS = {
  success: 'fa-circle-check',
  error: 'fa-circle-xmark',
  warning: 'fa-triangle-exclamation',
  info: 'fa-circle-info',
}

let counter = 0

/** Conteneur de toasts global. Écoute l'évènement window `mc-toast`. */
export default function Toasts() {
  const [toasts, setToasts] = useState([])

  useEffect(() => {
    const onToast = (e) => {
      const { message, type = 'info' } = e.detail || {}
      if (!message) return
      const id = ++counter
      setToasts((list) => [...list, { id, message, type }])
      setTimeout(() => {
        setToasts((list) => list.filter((t) => t.id !== id))
      }, 4500)
    }
    window.addEventListener('mc-toast', onToast)
    return () => window.removeEventListener('mc-toast', onToast)
  }, [])

  const dismiss = (id) => setToasts((list) => list.filter((t) => t.id !== id))

  return (
    <div className="toast-stack" role="status" aria-live="polite">
      {toasts.map((t) => (
        <div key={t.id} className={`toast toast-${t.type}`}>
          <i className={`fas ${ICONS[t.type] || ICONS.info}`}></i>
          <span>{t.message}</span>
          <button className="toast-close" onClick={() => dismiss(t.id)} aria-label="Fermer">
            <i className="fas fa-times"></i>
          </button>
        </div>
      ))}
    </div>
  )
}

import { createContext, useContext, useEffect, useState, useCallback } from 'react'
import { api, getToken, setToken } from '../api/client.js'

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [token, setTokenState] = useState(() => getToken())
  const isAuthenticated = !!token

  // logout if any request reports the token is no longer valid
  useEffect(() => {
    const onUnauth = () => setTokenState(null)
    window.addEventListener('mc-unauthorized', onUnauth)
    return () => window.removeEventListener('mc-unauthorized', onUnauth)
  }, [])

  const login = useCallback(async (username, password) => {
    const { token: t } = await api.post('/auth/login', { username, password })
    setToken(t)
    setTokenState(t)
  }, [])

  const logout = useCallback(() => {
    setToken(null)
    setTokenState(null)
  }, [])

  return (
    <AuthContext.Provider value={{ token, isAuthenticated, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const ctx = useContext(AuthContext)
  if (!ctx) throw new Error('useAuth must be used within AuthProvider')
  return ctx
}

import { createContext, useContext, useState, useCallback } from 'react'

const ThemeContext = createContext(null)

function getInitialTheme() {
  return localStorage.getItem('mc-theme') === 'dark' ? 'dark' : 'light'
}

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState(getInitialTheme)

  const toggleTheme = useCallback(() => {
    setTheme((prev) => {
      const next = prev === 'dark' ? 'light' : 'dark'
      if (next === 'dark') {
        document.documentElement.setAttribute('data-theme', 'dark')
        localStorage.setItem('mc-theme', 'dark')
      } else {
        document.documentElement.removeAttribute('data-theme')
        localStorage.setItem('mc-theme', 'light')
      }
      return next
    })
  }, [])

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}

export function useTheme() {
  const ctx = useContext(ThemeContext)
  if (!ctx) throw new Error('useTheme must be used within ThemeProvider')
  return ctx
}

