// mouvements.php : entrées + sorties fusionnées sur une période
export function getMouvements(dateDebut, dateFin) {
  const d1 = new Date(dateDebut)
  const d2 = new Date(dateFin)
  d2.setDate(d2.getDate() + 1)

  const entreesMvt = entrees
    .filter((e) => {
      const d = new Date(e.DATE_ENTREE)
      return d >= d1 && d <= d2
    })
    .map((e) => {
      const ls = lots.filter((l) => l.ID_ENTREE === e.ID_ENTREE)
      return {
        ID_ENTREE: e.ID_ENTREE,
        DATE_ENTREE: e.DATE_ENTREE,
        FOURNISSEUR: e.FOURNISSEUR,
        NB_LOTS: ls.length,
        QUANTITE: ls.reduce((s, l) => s + l.QUANTITE, 0),
        TYPE_MVT: 'Entrée',
      }
    })

  // sorties groupées par service + jour
  const groups = {}
  sorties
    .filter((so) => {
      const d = new Date(so.DATE_SORTIE)
      return d >= d1 && d <= d2
    })
    .forEach((so) => {
      const key = `${so.DATE_SORTIE}|${so.ID_SERVICE}`
      if (!groups[key]) {
        groups[key] = {
          ID_ENTREE: so.ID_SORTIE,
          DATE_ENTREE: so.DATE_SORTIE,
          FOURNISSEUR: services.find((s) => s.ID_SERVICE === so.ID_SERVICE)?.NOM_SERVICE ?? '',
          NB_LOTS: 0,
          QUANTITE: 0,
          TYPE_MVT: 'Sortie',
        }
      }
      groups[key].NB_LOTS += 1
      groups[key].QUANTITE += so.QUANTITE
      groups[key].ID_ENTREE = Math.min(groups[key].ID_ENTREE, so.ID_SORTIE)
    })

  return [...entreesMvt, ...Object.values(groups)].sort(
    (a, b) => new Date(b.DATE_ENTREE) - new Date(a.DATE_ENTREE),
  )
}

// statistiques.php
export function getStatistiques() {
  // top services
  const topServices = services
    .map((s) => {
      const ss = sorties.filter((so) => so.ID_SERVICE === s.ID_SERVICE)
      return {
        NOM_SERVICE: s.NOM_SERVICE,
        NB_SORTIES: ss.length,
        TOTAL_UNITES: ss.reduce((acc, so) => acc + so.QUANTITE, 0),
      }
    })
    .filter((s) => s.TOTAL_UNITES > 0)
    .sort((a, b) => b.TOTAL_UNITES - a.TOTAL_UNITES)

  // top médicaments (via lot -> médicament)
  const medAgg = {}
  sorties.forEach((so) => {
    const m = medOfLot(so.ID_LOT)
    if (!m) return
    if (!medAgg[m.ID_MEDICAMENT]) medAgg[m.ID_MEDICAMENT] = { NOM_MEDICAMENT: m.NOM_MEDICAMENT, NB_SORTIES: 0, TOTAL_UNITES: 0 }
    medAgg[m.ID_MEDICAMENT].NB_SORTIES += 1
    medAgg[m.ID_MEDICAMENT].TOTAL_UNITES += so.QUANTITE
  })
  const topMedicaments = Object.values(medAgg).sort((a, b) => b.TOTAL_UNITES - a.TOTAL_UNITES)

  // stats globales
  const totalEntrees = lots.reduce((s, l) => s + l.QUANTITE, 0)
  const totalSorties = sorties.reduce((s, so) => s + so.QUANTITE, 0)
  const totalPerime = lots.filter((l) => isPerime(l.DATE_PEREMPTION)).reduce((s, l) => s + l.QUANTITE, 0)
  const globalStats = {
    NB_MEDICAMENTS: medicaments.length,
    NB_SERVICES: services.length,
    NB_FOURNISSEURS: fournisseurs.length,
    TOTAL_SORTIES: totalSorties,
    TOTAL_ENTREES: totalEntrees,
    TOTAL_PERIME: totalPerime,
  }

  // évolution mensuelle
  const moisAgg = {}
  entrees.forEach((e) => {
    const mois = e.DATE_ENTREE.slice(0, 7)
    const qte = lots.filter((l) => l.ID_ENTREE === e.ID_ENTREE).reduce((s, l) => s + l.QUANTITE, 0)
    if (!moisAgg[mois]) moisAgg[mois] = { MOIS: mois, ENTREE_UNITES: 0, SORTIE_UNITES: 0 }
    moisAgg[mois].ENTREE_UNITES += qte
  })
  sorties.forEach((so) => {
    const mois = so.DATE_SORTIE.slice(0, 7)
    if (!moisAgg[mois]) moisAgg[mois] = { MOIS: mois, ENTREE_UNITES: 0, SORTIE_UNITES: 0 }
    moisAgg[mois].SORTIE_UNITES += so.QUANTITE
  })
  const mensuel = Object.values(moisAgg).sort((a, b) => a.MOIS.localeCompare(b.MOIS))

  // répartition par famille
  const famillesRep = familles
    .map((f) => {
      const ms = medicaments.filter((m) => m.ID_FAMILLE === f.ID_FAMILLE)
      return {
        NOM_FAMILLE: f.NOM_FAMILLE,
        NB_MEDICAMENTS: ms.length,
        TOTAL_STOCK: ms.reduce((s, m) => s + m.QUANTITE_DISPONIBLE, 0),
      }
    })
    .sort((a, b) => b.TOTAL_STOCK - a.TOTAL_STOCK)

  return { topServices, topMedicaments, globalStats, mensuel, familles: famillesRep }
}

