import { useCallback, useEffect, useState } from 'react'
import { api } from '../api/client.js'

/**
 * Récupère des données JSON depuis l'API.
 * Retourne { data, loading, error, refetch }. Re-fetch quand `deps` change.
 */
export function useApiData(path, deps = []) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  const refetch = useCallback(() => {
    let alive = true
    setLoading(true)
    setError(null)
    api
      .get(path)
      .then((d) => { if (alive) setData(d) })
      .catch((e) => { if (alive) setError(e.message) })
      .finally(() => { if (alive) setLoading(false) })
    return () => { alive = false }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [path, ...deps])

  useEffect(() => refetch(), [refetch])

  return { data, loading, error, refetch }
}

import { useGSAP } from '@gsap/react'
import gsap from 'gsap'

gsap.registerPlugin(useGSAP)

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Animate a number-only element from 0 to its printed value, preserving any
 * trailing suffix (e.g. "%"). Returns true if a count-up was started.
 */
function countUp(el, tl, position) {
  // Cache the target in a data-attribute so a re-run (e.g. React StrictMode's
  // double-invoke) doesn't read the already-zeroed textContent as the target.
  if (el.dataset.countTo === undefined) {
    const match = el.textContent.trim().match(/^(-?\d[\d\s.,]*)(\D*)$/)
    if (!match) return false
    const parsed = parseInt(match[1].replace(/[^\d-]/g, ''), 10)
    if (Number.isNaN(parsed) || parsed === 0) return false
    el.dataset.countTo = String(parsed)
    el.dataset.countSuffix = match[2] || ''
  }
  const end = Number(el.dataset.countTo)
  const suffix = el.dataset.countSuffix || ''
  const proxy = { v: 0 }
  el.textContent = `0${suffix}`
  tl.to(
    proxy,
    {
      v: end,
      duration: 1.1,
      ease: 'power2.out',
      snap: { v: 1 },
      onUpdate: () => {
        el.textContent = `${proxy.v}${suffix}`
      },
    },
    position,
  )
  return true
}

/**
 * Shared entrance choreography for the app shell. Scoped to `containerRef`,
 * re-runs whenever `routeKey` changes. Honors prefers-reduced-motion by
 * leaving everything in its natural, visible state.
 */
export function useEntranceAnimation(containerRef, routeKey) {
  useGSAP(
    () => {
      const root = containerRef.current
      if (!root || prefersReducedMotion()) return

      const q = (sel) => Array.from(root.querySelectorAll(sel))
      const tl = gsap.timeline({ defaults: { ease: 'power3.out' } })

      // Révèle des éléments avec un `from` SÛR : si le tween est interrompu
      // (re-rendu React quand les données async arrivent, double-invoke de
      // StrictMode en dev…), `from` laisserait sinon les éléments figés sur leur
      // état de départ invisible (autoAlpha:0). On nettoie donc les styles GSAP
      // à la fin (clearProps) ET en cas d'interruption (onInterrupt) pour
      // garantir qu'ils finissent TOUJOURS visibles.
      const revealFrom = (targets, vars, position) => {
        if (!targets.length) return
        const restore = () => gsap.set(targets, { clearProps: 'opacity,visibility,transform,translate,rotate,scale' })
        tl.from(targets, { ...vars, clearProps: 'opacity,visibility,transform,translate,rotate,scale', onInterrupt: restore }, position)
      }

      const statCells = q('.stat-cell')
      if (statCells.length) {
        revealFrom(statCells, { y: 18, autoAlpha: 0, duration: 0.55, stagger: 0.07 })
        // count-up numeric stat values alongside the reveal
        q('.stat-value').forEach((el) => countUp(el, tl, '<0.1'))
      }

      const sectionHead = q('.section-head, .filters-bar').slice(0, 1)
      revealFrom(sectionHead, { y: 14, autoAlpha: 0, duration: 0.5 }, '-=0.35')

      const rows = q('.data-table tbody tr')
      revealFrom(rows, { y: 12, autoAlpha: 0, duration: 0.4, stagger: { amount: 0.5 } }, '-=0.25')

      const cards = q('.record-card, .export-card, .chart-card, .mvt-item')
      revealFrom(cards, { y: 20, autoAlpha: 0, duration: 0.5, stagger: { amount: 0.4 } }, rows.length ? '-=0.3' : '-=0.2')

      // animate progress bars from 0 to their target width
      q('.progress-fill, .rank-bar-fill').forEach((el) => {
        const target = el.style.width || '0%'
        tl.fromTo(
          el,
          { width: '0%' },
          { width: target, duration: 0.7, ease: 'power2.out' },
          '<0.02',
        )
      })

      // Filet de sécurité au démontage / changement de route : on retire tout
      // style d'opacité/visibilité résiduel laissé par un tween interrompu, de
      // sorte qu'aucun élément ne puisse rester figé invisible.
      return () => {
        gsap.set(q('.stat-cell, .section-head, .filters-bar, .data-table tbody tr, .record-card, .export-card, .chart-card, .mvt-item'), {
          clearProps: 'opacity,visibility,transform,translate,rotate,scale',
        })
      }
    },
    { scope: containerRef, dependencies: [routeKey], revertOnUpdate: true },
  )
}

