function toCsv(rows) {
  return rows
    .map((r) => r.map((cell) => {
      const v = cell == null ? '' : String(cell)
      return /[",;\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v
    }).join(';'))
    .join('\r\n')
}

function download(type, rows) {
  const csv = '﻿' + toCsv(rows) // BOM UTF-8 (compatible Excel)
  const today = new Date().toISOString().slice(0, 10)
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  const a = document.createElement('a')
  a.href = url
  a.download = `medicastock_${type}_${today}.csv`
  document.body.appendChild(a)
  a.click()
  a.remove()
  URL.revokeObjectURL(url)
}

/** Récupère les données puis construit les lignes CSV pour un type d'export. */
async function buildRows(type) {
  if (type === 'medicaments') {
    const data = await api.get('/medicaments')
    const rows = [['ID', 'Nom', 'Famille', 'Stock', 'Seuil']]
    data.forEach((m) => rows.push([m.ID_MEDICAMENT, m.NOM_MEDICAMENT, m.NOM_FAMILLE, m.QUANTITE_DISPONIBLE, m.QUANTITE_SEUIL]))
    return rows
  }
  if (type === 'stocks') {
    const data = await api.get('/stocks')
    const rows = [['ID', 'Médicament', 'Famille', 'Stock dispo', 'Seuil', 'Nb lots', 'Total lots', 'Bonne', 'Périmée']]
    data.forEach((s) => rows.push([s.ID_MEDICAMENT, s.NOM_MEDICAMENT, s.NOM_FAMILLE, s.QUANTITE_DISPONIBLE, s.QUANTITE_SEUIL, s.NB_LOTS, s.QTE_TOTALE_LOTS, s.QTE_BONNE, s.QTE_PERIMEE]))
    return rows
  }
  if (type === 'services') {
    const data = await api.get('/services')
    const rows = [['ID', 'Service', 'Description', 'Nb sorties', 'Total unités']]
    data.forEach((s) => rows.push([s.ID_SERVICE, s.NOM_SERVICE, s.DESCRIPTION, s.NB_SORTIES, s.TOTAL_SORTIES]))
    return rows
  }
  if (type === 'fournisseurs') {
    const data = await api.get('/fournisseurs')
    const rows = [['ID', 'Nom', 'Téléphone', 'Email', 'Adresse']]
    data.forEach((f) => rows.push([f.ID_FOURNISSEUR, f.NOM_FOURNISSEUR, f.TELEPHONE, f.EMAIL, f.ADRESSE]))
    return rows
  }
  if (type === 'mouvements') {
    const data = await api.get('/mouvements?debut=2000-01-01&fin=2100-01-01')
    const rows = [['Type', 'Date', 'Référence', 'Quantité', 'Partenaire']]
    data.forEach((m) => rows.push([m.TYPE_MVT, m.DATE_ENTREE, m.ID_ENTREE, m.QUANTITE, m.FOURNISSEUR]))
    return rows
  }
  return [[]]
}

export default function Exports() {
  const countsQ = useApiData('/exports/counts')
  const counts = countsQ.data ?? { totalMedicaments: '…', totalLots: '…', totalMouvements: '…' }
  const [busy, setBusy] = useState(null)
  const [error, setError] = useState(null)

  const CARDS = [
    { type: 'medicaments', icon: 'fa-pills', cls: 'csv', title: 'Médicaments', desc: `${counts.totalMedicaments} médicaments · Catalogue complet` },
    { type: 'stocks', icon: 'fa-boxes-stacked', cls: 'xls', title: 'Situation des stocks', desc: `${counts.totalLots} lots · Vue détaillée par médicament` },
    { type: 'services', icon: 'fa-hospital', cls: 'pdf', title: 'Services', desc: 'Liste des services et consommations' },
    { type: 'fournisseurs', icon: 'fa-truck', cls: 'csv', title: 'Fournisseurs', desc: 'Répertoire complet des fournisseurs' },
    { type: 'mouvements', icon: 'fa-arrow-right-arrow-left', cls: 'xls', title: 'Mouvements', desc: `${counts.totalMouvements} mouvements · Historique complet` },
  ]

  const handleExport = async (type) => {
    setError(null)
    setBusy(type)
    try {
      const rows = await buildRows(type)
      download(type, rows)
    } catch (err) {
      setError(err.message)
    } finally {
      setBusy(null)
    }
  }

  return (
    <Layout title="Exports" ready={!countsQ.loading}>
      <div className="section-head">
        <div>
          <div className="section-title">Exporter les données</div>
          <div className="section-count">Générez des fichiers CSV de vos données</div>
        </div>
      </div>

      {error && <ErrorState message={error} />}

      <div className="export-grid">
        {CARDS.map((c) => (
          <a
            key={c.type}
            href="#"
            className="export-card"
            onClick={(e) => { e.preventDefault(); if (!busy) handleExport(c.type) }}
            style={busy && busy !== c.type ? { opacity: 0.5, pointerEvents: 'none' } : undefined}
          >
            <div className={`export-icon ${c.cls}`}>
              <i className={`fas ${busy === c.type ? 'fa-spinner fa-spin' : c.icon}`}></i>
            </div>
            <div className="export-title">{c.title}</div>
            <div className="export-desc">{c.desc}</div>
          </a>
        ))}
      </div>

      <div className="form-card" style={{ marginTop: 40 }}>
        <div className="form-card-title">Format d'export</div>
        <div className="form-card-sub">Tous les exports sont générés au format CSV (UTF-8 BOM), compatible Excel, LibreOffice et Google Sheets.</div>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap', marginTop: 12 }}>
          <span className="badge badge-green"><i className="fas fa-file-csv"></i> CSV UTF-8</span>
          <span className="badge badge-blue"><i className="fas fa-table"></i> Compatible Excel</span>
          <span className="badge badge-amber"><i className="fas fa-clock"></i> Données temps réel</span>
        </div>
      </div>
    </Layout>
  )
}

