const pad = (n, len) => String(n).padStart(len, '0')

export default function Fournisseurs() {
  const q = useApiData('/fournisseurs')
  const fournisseurs = q.data ?? []
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [confirmTarget, setConfirmTarget] = useState(null)
  const [submitting, setSubmitting] = useState(false)

  const openCreate = () => { setEditing(null); setOpen(true) }
  const openEdit = (f) => { setEditing(f); setOpen(true) }

  const handleSubmit = async (e) => {
    e.preventDefault()
    const f = new FormData(e.target)
    const nom = (f.get('nom_fournisseur') || '').toString().trim()
    const payload = {
      nom_fournisseur: nom,
      telephone: f.get('telephone'),
      email: f.get('email'),
      adresse: f.get('adresse'),
    }
    setSubmitting(true)
    try {
      if (editing) {
        await api.put(`/fournisseurs/${editing.ID_FOURNISSEUR}`, payload)
        toast(`Fournisseur « ${nom} » mis à jour.`, 'success')
      } else {
        await api.post('/fournisseurs', payload)
        toast(`Fournisseur « ${nom} » ajouté.`, 'success')
      }
      setOpen(false)
      q.refetch()
    } catch (err) {
      toast(err.message, 'error')
    } finally {
      setSubmitting(false)
    }
  }

  const handleDelete = async () => {
    if (!confirmTarget) return
    setSubmitting(true)
    try {
      await api.del(`/fournisseurs/${confirmTarget.ID_FOURNISSEUR}`)
      toast(`Fournisseur « ${confirmTarget.NOM_FOURNISSEUR} » supprimé.`, 'success')
      setConfirmTarget(null)
      q.refetch()
    } catch (err) {
      toast(err.message, 'error')
    } finally {
      setSubmitting(false)
    }
  }

  const actions = (
    <button className="btn-action" onClick={openCreate}>
      <i className="fas fa-plus"></i> Nouveau fournisseur
    </button>
  )

  return (
    <Layout title="Fournisseurs" actions={actions} ready={!q.loading}>
      <div className="section-head">
        <div>
          <div className="section-title">Répertoire des fournisseurs</div>
          <div className="section-count">{fournisseurs.length} fournisseurs</div>
        </div>
      </div>

      {q.loading ? (
        <Loading />
      ) : q.error ? (
        <ErrorState message={q.error} onRetry={q.refetch} />
      ) : fournisseurs.length === 0 ? (
        <div className="empty-state" style={{ background: 'var(--surface-card)', border: '1px solid var(--rule)', borderRadius: 12, padding: '80px 20px' }}>
          <i className="fas fa-truck"></i>
          <p>Aucun fournisseur enregistré.</p>
          <button className="btn-primary" style={{ marginTop: 16 }} onClick={openCreate}>
            <i className="fas fa-plus"></i> Ajouter un fournisseur
          </button>
        </div>
      ) : (
        <div className="cards-grid">
          {fournisseurs.map((f) => (
            <div className="record-card" key={f.ID_FOURNISSEUR}>
              <div className="record-card-title">
                <i className="fas fa-building" style={{ color: 'var(--blue)', marginRight: 8, fontSize: 12 }}></i>
                {f.NOM_FOURNISSEUR}
              </div>
              {f.TELEPHONE && <div className="record-card-sub"><i className="fas fa-phone" style={{ width: 14, fontSize: 10 }}></i> {f.TELEPHONE}</div>}
              {f.EMAIL && <div className="record-card-sub"><i className="fas fa-envelope" style={{ width: 14, fontSize: 10 }}></i> {f.EMAIL}</div>}
              {f.ADRESSE && <div className="record-card-sub"><i className="fas fa-location-dot" style={{ width: 14, fontSize: 10 }}></i> {f.ADRESSE}</div>}
              <div className="record-card-actions" style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <span className="badge badge-blue">#{pad(f.ID_FOURNISSEUR, 3)}</span>
                <div className="row-actions">
                  <button className="icon-btn" title="Modifier" onClick={() => openEdit(f)}><i className="fas fa-pen"></i></button>
                  <button className="icon-btn danger" title="Supprimer" onClick={() => setConfirmTarget(f)}><i className="fas fa-trash"></i></button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      <Modal open={open} onClose={() => setOpen(false)}>
        <form onSubmit={handleSubmit} key={editing?.ID_FOURNISSEUR ?? 'new'}>
          <div className="modal-header">
            <div className="modal-title">{editing ? 'Modifier le fournisseur' : 'Nouveau fournisseur'}</div>
            <button type="button" className="modal-close" onClick={() => setOpen(false)}><i className="fas fa-times"></i></button>
          </div>
          <div className="modal-body">
            <div className="form-grid">
              <div className="form-group full">
                <label htmlFor="nom_fournisseur">Nom du fournisseur</label>
                <input type="text" id="nom_fournisseur" name="nom_fournisseur" className="form-control" placeholder="Ex: PharmaLab SARL" defaultValue={editing?.NOM_FOURNISSEUR ?? ''} required />
              </div>
              <div className="form-group">
                <label htmlFor="telephone">Téléphone</label>
                <input type="text" id="telephone" name="telephone" className="form-control" placeholder="Ex: +229 01 23 45 67" defaultValue={editing?.TELEPHONE ?? ''} />
              </div>
              <div className="form-group">
                <label htmlFor="email">Email</label>
                <input type="email" id="email" name="email" className="form-control" placeholder="contact@fournisseur.com" defaultValue={editing?.EMAIL ?? ''} />
              </div>
              <div className="form-group full">
                <label htmlFor="adresse">Adresse</label>
                <textarea id="adresse" name="adresse" className="form-control" rows={2} placeholder="Adresse complète" defaultValue={editing?.ADRESSE ?? ''}></textarea>
              </div>
            </div>
          </div>
          <div className="modal-footer">
            <button type="button" className="btn-ghost" onClick={() => setOpen(false)}>Annuler</button>
            <button type="submit" className="btn-primary" disabled={submitting}>
              <i className={`fas fa-${editing ? 'check' : 'plus'}`}></i> {editing ? 'Enregistrer' : 'Ajouter'}
            </button>
          </div>
        </form>
      </Modal>

      <ConfirmModal
        open={!!confirmTarget}
        title="Supprimer le fournisseur"
        message={confirmTarget ? `Supprimer « ${confirmTarget.NOM_FOURNISSEUR} » ? Cette action est irréversible.` : ''}
        confirmLabel="Supprimer"
        busy={submitting}
        onConfirm={handleDelete}
        onCancel={() => setConfirmTarget(null)}
      />
    </Layout>
  )
}

