/* ── Interactive SVG grid (hover handled by CSS) ── */
function HeroGrid() {
  const cols = 40
  const rows = 25
  const rects = []
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      rects.push(
        <rect
          key={`${i}-${j}`}
          x={`${(j * 100) / cols}%`}
          y={`${(i * 100) / rows}%`}
          width={`${100 / cols}%`}
          height={`${100 / rows}%`}
        />,
      )
    }
  }
  return (
    <div className="hero-grid-bg">
      <svg width="100%" height="100%">{rects}</svg>
    </div>
  )
}

function MiniGrid() {
