  const [activeIdx, setActiveIdx] = useState(0)
  const navRef = useRef(null)
  const indicatorRef = useRef(null)
  const linkRefs = useRef([])
  const heroVideoRef = useRef(null)

  // respecte "réduire les animations" : on fige la vidéo de fond du hero
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)')
    const apply = () => {
      const v = heroVideoRef.current
      if (!v) return
      if (mq.matches) v.pause()
      else v.play().catch(() => {})
    }
    apply()
    mq.addEventListener('change', apply)
    return () => mq.removeEventListener('change', apply)
  }, [])

  // navbar scroll effect
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 50)
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  // nav indicator position
  const positionIndicator = (idx) => {
    const link = linkRefs.current[idx]
    const indicator = indicatorRef.current
    if (!link || !indicator) return
    const wrapper = link.parentElement
    const parent = wrapper.parentElement
    const parentRect = parent.getBoundingClientRect()
    const wrapperRect = wrapper.getBoundingClientRect()
    indicator.style.left = wrapperRect.left - parentRect.left + 'px'
    indicator.style.width = wrapperRect.width + 'px'
  }

  useEffect(() => {
    positionIndicator(activeIdx)
    const onResize = () => positionIndicator(activeIdx)
    window.addEventListener('resize', onResize)
    return () => window.removeEventListener('resize', onResize)
    // eslint-disable-next-line react-hooks/exhaustive-deps
